<?php
namespace App\Tests\Entity;
use App\Entity\ChatMessage;use App\Entity\Conversation;use App\Entity\User;use PHPUnit\Framework\TestCase;
final class ChatMessageTest extends TestCase{private function user():User{return(new User())->setUsername('alice')->setEmail(uniqid().'@test.local')->setPasswordHash('x')->setStatus('ACTIVE');}public function testEmptyMessageIsRejected():void{$u=$this->user();$this->expectException(\InvalidArgumentException::class);new ChatMessage(new Conversation(Conversation::DIRECT,$u,null,'a:b'),$u,'  ');}public function testTooLongMessageIsRejected():void{$u=$this->user();$this->expectException(\InvalidArgumentException::class);new ChatMessage(new Conversation(Conversation::DIRECT,$u,null,'a:b'),$u,str_repeat('x',2001));}public function testEditAndLogicalDeletePreserveContentForAudit():void{$u=$this->user();$m=new ChatMessage(new Conversation(Conversation::DIRECT,$u,null,'a:b'),$u,'Bonjour');$m->edit('Salut')->delete();self::assertSame('Salut',$m->getContent());self::assertNotNull($m->getEditedAt());self::assertTrue($m->isDeleted());}}
